from pathlib import Path
import json,math,hashlib,numpy as np
P=Path(__file__).resolve().parent;root=P.parents[3];checks={}
for file in ['protected-inputs.json','additional-inputs.json','connector-inputs.json']:
 for p,h in json.loads((P/file).read_text()).items():
  assert hashlib.sha256((root/p).read_bytes()).hexdigest()==h,p;checks[p]=h
fixed=json.loads((P/'fanout-probe.json').read_text());moving=json.loads((P/'moving-path.json').read_text());wire=json.loads((P/'source-wire-paths.json').read_text());a=np.array(moving['samples']);ml=float(np.linalg.norm(np.diff(a[:,:3],axis=0),axis=1).sum());fl=fixed['length'];b=.3/(2*math.pi);tt=np.linspace(-.3,0,8193);tailfixed=float(np.trapezoid(np.sqrt((25+b*tt)**2+b*b),tt));tt=np.linspace(0,.3,8193);tailmoving=float(np.trapezoid(np.sqrt((30.5+b*tt)**2+b*b),tt));static=ml+fl+tailfixed+tailmoving
rho=.017241;factor=1+.00393*60;rfpc=2*rho*(static/1000)/(7.8*.063)*factor;rw=rho*sum(x['length'] for x in wire.values())/1000/(math.pi/4)*factor
out={'protected_hashes':len(checks),'fixed_extension_mm':fl,'moving_extension_mm':ml,'fixed_tail_mm':tailfixed,'moving_tail_mm':tailmoving,'total_static_flex_trace_length_each_mm':static,'active_length_each_mm':1046.167655992167,'static_flex_hot_loop_ohm':rfpc,'wire_hot_loop_ohm_nominal_1mm_copper':rw,'stress_A':2,'static_plus_wire_drop_at_2A':2*(rfpc+rw),'static_plus_wire_heat_at_2A':4*(rfpc+rw),'assumptions':{'copper_rho_20C_ohm_mm2_per_m':rho,'temp_coefficient':.00393,'copper_temp_C':80,'flex_finished_width_mm':7.8,'flex_copper_thickness_mm':.063,'wire_copper_diameter_mm_nominal_only':1,'termination_resistance':'UNKNOWN, not zero; not included','current':'2A engineering stress, NOT instantaneous fault bound or ampacity grant'},'wire_paths':{k:{j:v for j,v in x.items() if j!='samples'} for k,x in wire.items()},'fixed_min_radius':fixed['min_bend_radius'],'fixed_active181_gap':fixed['minimum_active_gap'],'connector_axial_lower_bound_deltas_mm':{'classic':12.8,'TRUE1':16.0,'NEMA':40.9},'source_electrical_or_lifetime_qualified':False}
(P/'numeric-check.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({k:v for k,v in out.items() if k not in ['wire_paths','assumptions']},indent=2))
